    {selected && <section className="card statement-card"><SectionTitle title={`گردش ${selected.name}`} action={<button className="button button-text" onClick={() => setSelected(null)}>بستن</button>} />{statement.isPending ? <LoadingBlock /> : statement.isError ? <InlineError error={statement.error} retry={() => void statement.refetch()} /> : statement.data?.entries.length ? <DataRows icon={FileText} rows={statement.data.entries.map((row) => ({ id: row.id, title: row.description || "سند مالی", subtitle: jalaliDate(row.date), amount: money(row.debitRial !== "0" ? row.debitRial : row.creditRial, currency) }))} emptyTitle="بدون گردش" emptyText="گردش ثبت‌شده‌ای وجود ندارد." /> : <EmptyState icon={FileText} title="گردشی ثبت نشده" text="با ثبت فروش، خرید یا دریافت و پرداخت، گردش حساب اینجا دیده می‌شود." />}</section>}
