export function InventoryPage({ currency }: { currency: MoneyCurrency }) {
  const invalidate = useInvalidate(); const [confirmCount, setConfirmCount] = useState<StockCount | null>(null); const [deleteCount, setDeleteCount] = useState<StockCount | null>(null); const [editCountId, setEditCountId] = useState<string | null>(null); const [counting, setCounting] = useState(false); const [quickProductOpen, setQuickProductOpen] = useState(false); const [countDate, setCountDate] = useState(() => todayISO()); const [countReason, setCountReason] = useState(""); const [countProductId, setCountProductId] = useState(""); const [countLines, setCountLines] = useState<CountDraftLine[]>([]); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const [exporting, setExporting] = useState(false);
  const stockProductPickerOptions = productPicker("STOCK");
  const rows = useInfiniteQuery({ queryKey: ["inventory"], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => get<CursorPage<InventoryRow>>(`/reports/inventory?limit=50${pageParam ? `&cursor=${encodeURIComponent(pageParam)}` : ""}`), getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined }); const inventoryRows = rows.data?.pages.flatMap((page) => page.items) ?? [];
  const levels = useInfiniteQuery({ queryKey: ["inventory-levels"], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => get<CursorPage<InventoryLevel>>(`/inventory/levels?limit=50${pageParam ? `&cursor=${encodeURIComponent(pageParam)}` : ""}`), getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined }); const levelRows = levels.data?.pages.flatMap((page) => page.items) ?? [];
  const counts = useInfiniteQuery({ queryKey: ["stock-counts"], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => get<CursorPage<StockCount>>(`/inventory/counts?limit=50${pageParam ? `&cursor=${encodeURIComponent(pageParam)}` : ""}`), getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined }); const countRows = counts.data?.pages.flatMap((page) => page.items) ?? [];
  const selectedCountLevel = levelRows.find((item) => item.productId === countProductId);
  const selectedCountProduct = useQuery({ queryKey: ["count-product", countProductId], queryFn: () => get<Product>(`/products/${countProductId}`), enabled: Boolean(countProductId) && !selectedCountLevel });
  const addCountLine = () => { const level = selectedCountLevel; const product = selectedCountProduct.data; const productId = level?.productId ?? product?.id; const productName = level?.name ?? product?.name; const quantity = level?.quantity ?? product?.quantityOnHand; const unitLabel = level?.unit.labelFa ?? product?.unit.labelFa; if (!productId || productName === undefined || quantity === undefined || unitLabel === undefined) return; setCountLines((current) => current.some((line) => line.productId === productId) ? current : [...current, { productId, countedQuantity: quantity, productName, unitLabel, systemQuantity: quantity }]); setCountProductId(""); };
  const createCount = async (event: FormEvent) => { event.preventDefault(); if (countLines.length === 0) { setError("برای شمارش، دست‌کم یک کالا اضافه کنید."); return; } setBusy(true); setError(""); try { const values = { txnDate: countDate, reason: countReason, lines: countLines.map(({ productId, countedQuantity }) => ({ productId, countedQuantity })) }; if (editCountId) await patch("/inventory/counts/" + editCountId, values); else await post("/inventory/counts", values); setCountLines([]); setCountReason(""); setEditCountId(null); setCounting(false); await invalidate(); } catch (cause) { setError(messageOf(cause)); } finally { setBusy(false); } };
  const editCount = (count: StockCount) => { setEditCountId(count.id); setCountDate(count.txnDate); setCountReason(count.reason); setCountLines(count.lines.map((line) => ({ productId: line.productId, countedQuantity: line.countedQuantity, productName: line.product, unitLabel: line.unit, systemQuantity: line.systemQuantity }))); setError(""); setCounting(true); };
  const deleteDraftCount = async () => { if (!deleteCount) return; setBusy(true); setError(""); try { await del("/inventory/counts/" + deleteCount.id); setDeleteCount(null); await invalidate(); } catch (cause) { setError(messageOf(cause)); } finally { setBusy(false); } };
  const postCount = async (id: string) => { setBusy(true); setError(""); try { await post(`/inventory/counts/${id}/post`, {}, { "Idempotency-Key": newOperationId() }); await invalidate(); return true; } catch (cause) { setError(messageOf(cause)); return false; } finally { setBusy(false); } };
  const exportInventory = async () => {
    setExporting(true); setError("");
    try {
      const allRows: InventoryRow[] = []; let cursor: string | null = null;
      do {
        const params = new URLSearchParams({ limit: "100" }); if (cursor) params.set("cursor", cursor);
        const page = await get<CursorPage<InventoryRow>>(`/reports/inventory?${params.toString()}`);
        allRows.push(...page.items);
        if (allRows.length > 10_000) throw new Error("موجودی بیش از سقف ۱۰٬۰۰۰ ردیف است؛ فایل ناقص ساخته نشد.");
        cursor = page.nextCursor;
      } while (cursor);
      downloadCsv("shopro-inventory.csv", [["گزارش", "ارزش موجودی فعلی"], ["تعداد ردیف", String(allRows.length)], ["واحد ارزش", "ریال"], [], ["کالا", "کد کالا", "موجودی", "واحد", "میانگین بهای تمام‌شده (ریال)", "ارزش موجودی (ریال)", "وضعیت حد سفارش"], ...allRows.map((item) => [item.name, item.sku ?? "", item.quantity, item.unit, item.averageCostRial, item.valueRial, item.low ? "کمتر از حد سفارش" : "عادی"]) ]);
    } catch (cause) { setError(messageOf(cause)); }
    finally { setExporting(false); }
  };
  return <PageHeader title="موجودی انبار" subtitle="وضعیت کالاها و ارزش موجودی این شعبه" actions={<><button className="button button-secondary" type="button" disabled={exporting || rows.isPending} onClick={() => void exportInventory()}><Download size={17} />{exporting ? "در حال آماده‌سازی…" : "دریافت CSV کامل"}</button><Link className="button button-secondary" to="/app/products"><PackagePlus size={17} />مدیریت کالاها</Link><button className="button button-primary" type="button" onClick={() => { setEditCountId(null); setCountDate(todayISO()); setCountReason(""); setCountLines([]); setError(""); setCounting(true); }}><RotateCw size={17} />شمارش موجودی</button></>}>
    {error && <InlineError error={error} />}{rows.isError && <InlineError error={rows.error} retry={() => void rows.refetch()} />}{rows.isPending ? <LoadingBlock /> : <><div className="metric-grid inventory-metrics"><MetricCard label="اقلام انبار" value={faNumber(inventoryRows.length)} detail="در موارد بارگذاری‌شده" icon={Boxes} tone="emerald" /><MetricCard label="کمبود موجودی" value={faNumber(inventoryRows.filter((item) => item.low).length)} detail="در موارد بارگذاری‌شده" icon={RotateCw} tone="amber" /></div><div className="card table-card"><div className="table-head inventory-head"><span>کالا</span><span>موجودی</span><span>ارزش موجودی</span></div>{inventoryRows.map((item) => <div className="table-row inventory-row" key={item.productId}><span className="table-name"><span className={`product-avatar ${item.low ? "warn" : ""}`}><Boxes size={17} /></span><span><strong>{item.name}</strong><small>{item.sku || "بدون کد"}</small></span></span><span className={item.low ? "stock-warning" : ""}>{faNumber(item.quantity)} {item.unit}</span><strong>{money(item.valueRial, currency)}</strong></div>)}{!inventoryRows.length && <EmptyState icon={Boxes} title="موجودی برای نمایش نیست" text="پس از ثبت خرید یا تعریف موجودی، فهرست کالاها اینجا نمایش داده می‌شود." />}</div><LoadMoreButton hasMore={Boolean(rows.hasNextPage)} isLoading={rows.isFetchingNextPage} onClick={() => void rows.fetchNextPage()} /></>}
    {counting && <Modal open={counting} onClose={() => { setCounting(false); setEditCountId(null); }} title={editCountId ? "ویرایش پیش‌نویس شمارش" : "شمارش فیزیکی"} description="موجودی هر کالا را ثبت و پیش از اعمال تعدیل بررسی کنید." size="wide"><form className="card inline-form stock-count-form" onSubmit={(event) => void createCount(event)}><SectionTitle title={editCountId ? "ویرایش شمارش فیزیکی" : "شمارش فیزیکی"} /><p className="muted">موجودی سیستم هنگام شروع شمارش ثبت می‌شود؛ اگر در همین فاصله گردش کالا تغییر کند، ثبت نهایی متوقف می‌شود.</p><div className="form-grid"><JalaliDatePicker value={countDate} onChange={setCountDate} label="تاریخ شمارش" /><Field label="دلیل شمارش" value={countReason} onChange={setCountReason} required placeholder="مثلاً شمارش دوره‌ای" /></div><div className="form-grid"><SelectField label="افزودن کالا" value={countProductId} onChange={setCountProductId} options={levelRows.filter((item) => !countLines.some((line) => line.productId === item.productId)).map((item) => ({ value: item.productId, label: `${item.name} · ${item.unit.labelFa}` }))} optionsKey={stockProductPickerOptions.key} loadOptions={stockProductPickerOptions.load} placeholder="انتخاب کالا" onAdd={() => setQuickProductOpen(true)} /><button className="button button-secondary" type="button" onClick={addCountLine} disabled={!countProductId || (!selectedCountLevel && selectedCountProduct.isPending)}>{selectedCountProduct.isFetching && !selectedCountLevel ? "در حال دریافت موجودی…" : "افزودن کالا به شمارش"}</button></div>{selectedCountProduct.isError && !selectedCountLevel && <InlineError error={selectedCountProduct.error} retry={() => void selectedCountProduct.refetch()} />}<LoadMoreButton hasMore={Boolean(levels.hasNextPage)} isLoading={levels.isFetchingNextPage} onClick={() => void levels.fetchNextPage()} />{countLines.length > 0 && <div className="stock-count-lines">{countLines.map((line) => { const level = levelRows.find((candidate) => candidate.productId === line.productId); const item = { name: level?.name ?? line.productName, quantity: level?.quantity ?? line.systemQuantity, unit: { labelFa: level?.unit.labelFa ?? line.unitLabel } }; return <div className="stock-count-line" key={line.productId}><span className="row-grow"><strong>{item.name}</strong><small>موجودی سیستم: {faNumber(item.quantity)} {item.unit.labelFa}</small></span><label className="field"><span className="field-label">شمارش‌شده ({item.unit.labelFa})</span><input inputMode="decimal" value={line.countedQuantity} onChange={(event) => setCountLines((current) => current.map((entry) => entry.productId === line.productId ? { ...entry, countedQuantity: event.target.value } : entry))} required /></label><button className="remove-line" type="button" aria-label={`حذف ${item.name}`} onClick={() => setCountLines((current) => current.filter((entry) => entry.productId !== line.productId))}><XIcon /></button></div>; })}</div>}{error && <InlineError error={error} />}<SubmitButton busy={busy}>{editCountId ? "ذخیرهٔ تغییرات" : "ذخیرهٔ پیش‌نویس شمارش"}</SubmitButton></form></Modal>}
    <section className="card stock-count-history"><SectionTitle title="شمارش‌های اخیر" /><Modal open={!!confirmCount} onClose={() => setConfirmCount(null)} title="ثبت نهایی شمارش" description="با تأیید، اختلاف موجودی در انبار و اسناد مالی اعمال می‌شود."><p>شمارش «{confirmCount?.reason}» نهایی شود؟</p>{error && <InlineError error={error} />}<div className="modal-form-actions"><button type="button" className="button button-danger" disabled={busy} onClick={async () => { if (confirmCount && await postCount(confirmCount.id)) setConfirmCount(null); }}>{busy ? "در حال ثبت…" : "تأیید و اعمال تعدیل"}</button></div></Modal><Modal open={!!deleteCount} onClose={() => setDeleteCount(null)} title="حذف پیش‌نویس شمارش" description="این پیش‌نویس هنوز اثری در موجودی و دفتر مالی ندارد."><p>پیش‌نویس «{deleteCount?.reason}» حذف شود؟</p>{error && <InlineError error={error} />}<div className="modal-form-actions"><button type="button" className="button button-danger" disabled={busy} onClick={() => void deleteDraftCount()}>{busy ? "در حال حذف…" : "تأیید حذف"}</button></div></Modal><QuickProductModal open={quickProductOpen} currency={currency} onClose={() => setQuickProductOpen(false)} onCreated={(product) => { setCountProductId(product.id); void invalidate(); }} />{counts.isError && <InlineError error={counts.error} retry={() => void counts.refetch()} />}{counts.isPending ? <LoadingBlock /> : countRows.length ? countRows.map((count) => <article className="stock-count-card" key={count.id}><div className="stock-count-summary"><div><strong>{count.reason}</strong><small>{jalaliDate(count.txnDate)} · {faNumber(count.lines.length)} کالا</small></div><span className={`status-badge ${count.status.toLowerCase()}`}>{count.status === "POSTED" ? "ثبت قطعی" : "پیش‌نویس"}</span></div><div className="stock-count-preview">{count.lines.slice(0, 4).map((line) => <span key={line.productId}>{line.product}: {faNumber(line.systemQuantity)} ← {faNumber(line.countedQuantity)} {line.unit}</span>)}{count.lines.length > 4 && <small>و {faNumber(count.lines.length - 4)} قلم دیگر</small>}</div><Link className="button button-text" to={"/app/inventory/counts/" + count.id}>مشاهدهٔ جزئیات کامل</Link>{count.status === "DRAFT" && <div className="detail-actions"><button className="button button-secondary" type="button" disabled={busy} onClick={() => editCount(count)}>ویرایش پیش‌نویس</button><button className="button button-secondary" type="button" disabled={busy} onClick={() => setConfirmCount(count)}>ثبت نهایی</button><button className="button button-danger" type="button" disabled={busy} onClick={() => setDeleteCount(count)}>حذف پیش‌نویس</button></div>}</article>) : <EmptyState icon={RotateCw} title="شمارشی ثبت نشده" text="تفاوت شمارش فیزیکی و موجودی سیستم با دلیل و سند حسابداری ثبت می‌شود." />}<LoadMoreButton hasMore={Boolean(counts.hasNextPage)} isLoading={counts.isFetchingNextPage} onClick={() => void counts.fetchNextPage()} /></section>
  </PageHeader>;
}

export function PurchasesPage({ currency }: { currency: MoneyCurrency }) {
  const invalidate = useInvalidate(); const navigate = useNavigate(); const [adding, setAdding] = useState(false); const [quickPartyOpen, setQuickPartyOpen] = useState(false); const [quickProductOpen, setQuickProductOpen] = useState(false); const [date, setDate] = useState(() => todayISO()); const [supplierId, setSupplierId] = useState(""); const [productId, setProductId] = useState(""); const [quantity, setQuantity] = useState("1"); const [unitCost, setUnitCost] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  const purchases = useInfiniteQuery({ queryKey: ["purchases"], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => get<CursorPage<Purchase>>(`/purchases?limit=50${pageParam ? `&cursor=${encodeURIComponent(pageParam)}` : ""}`), getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined }); const purchaseRows = purchases.data?.pages.flatMap((page) => page.items) ?? []; const suppliers = useQuery({ queryKey: ["parties", "SUPPLIER"], queryFn: () => get<Party[]>("/parties?type=SUPPLIER") }); const products = useQuery({ queryKey: ["products"], queryFn: () => get<Product[]>("/products") });
  const supplierPickerOptions = partyPicker("SUPPLIER"); const stockProductPickerOptions = productPicker("STOCK");
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!productId) { setError("یک کالا را انتخاب کنید."); return; } setBusy(true); setError(""); try { const priceRial = displayToRial(unitCost, currency); const draft = await post<{ id: string }>("/purchases", { supplierId: supplierId || undefined, txnDate: date, lines: [{ productId, quantity, unitCostRial: priceRial }] }); setAdding(false); setProductId(""); setUnitCost(""); await invalidate(); navigate("/app/purchases/" + draft.id); } catch (cause) { setError(messageOf(cause)); } finally { setBusy(false); } };
  return <PageHeader title="خرید" subtitle="ثبت خرید و افزایش موجودی کالا" actions={<button className="button button-primary" onClick={() => setAdding(!adding)}><ShoppingBag size={17} />ثبت خرید</button>}>
    {adding && <Modal open={adding} onClose={() => setAdding(false)} title="خرید جدید" description="پیش‌نویس خرید را بسازید؛ پیش از اعمال موجودی و سند حسابداری می‌توانید آن را ویرایش یا حذف کنید." size="wide"><form className="card inline-form" onSubmit={(event) => void submit(event)}><SectionTitle title="خرید جدید" /><div className="form-grid"><JalaliDatePicker value={date} onChange={setDate} label="تاریخ خرید" /><SelectField label="تأمین‌کننده" value={supplierId} onChange={setSupplierId} options={(suppliers.data ?? []).map((item) => ({ value: item.id, label: item.name }))} optionsKey={supplierPickerOptions.key} loadOptions={supplierPickerOptions.load} placeholder="انتخاب تأمین‌کننده" onAdd={() => setQuickPartyOpen(true)} /><SelectField label="کالا" value={productId} onChange={setProductId} options={(products.data ?? []).filter((item) => item.kind === "STOCK").map((item) => ({ value: item.id, label: item.name }))} optionsKey={stockProductPickerOptions.key} loadOptions={stockProductPickerOptions.load} onAdd={() => setQuickProductOpen(true)} /><Field label="تعداد" value={quantity} onChange={setQuantity} inputMode="decimal" required /><Field label={`بهای هر واحد (${currency === "IRT" ? "تومان" : "ریال"})`} value={unitCost} onChange={setUnitCost} inputMode={currency === "IRT" ? "decimal" : "numeric"} required /></div>{error && <p className="form-error">{error}</p>}<SubmitButton busy={busy}>ذخیرهٔ پیش‌نویس خرید</SubmitButton></form></Modal>}
    <QuickPartyModal open={quickPartyOpen} type="SUPPLIER" onClose={() => setQuickPartyOpen(false)} onCreated={(party) => { setSupplierId(party.id); void invalidate(); }} /><QuickProductModal open={quickProductOpen} currency={currency} onClose={() => setQuickProductOpen(false)} onCreated={(product) => { setProductId(product.id); void invalidate(); }} />{purchases.isError && <InlineError error={purchases.error} retry={() => void purchases.refetch()} />}{purchases.isPending ? <LoadingBlock /> : <><DataRows icon={ShoppingBag} onRowClick={(id) => navigate("/app/purchases/" + id)} rows={purchaseRows.map((item) => ({ id: item.id, title: item.purchaseNo ?? "پیش‌نویس خرید", subtitle: `${item.supplier ?? "بدون تأمین‌کننده"} · ${jalaliDate(item.date)}`, amount: money(item.totalRial, currency), status: statusLabel(item.status) }))} emptyTitle="خریدی ثبت نشده" emptyText="ثبت خرید، موجودی کالا را بر اساس سند افزایش می‌دهد." /><LoadMoreButton hasMore={Boolean(purchases.hasNextPage)} isLoading={purchases.isFetchingNextPage} onClick={() => void purchases.fetchNextPage()} /></>}
  </PageHeader>;
}

export function ExpensesPage({ currency }: { currency: MoneyCurrency }) {
  const invalidate = useInvalidate(); const navigate = useNavigate(); const [adding, setAdding] = useState(false); const [quickPartyOpen, setQuickPartyOpen] = useState(false); const [quickCategoryOpen, setQuickCategoryOpen] = useState(false); const [payeeId, setPayeeId] = useState(""); const [date, setDate] = useState(() => todayISO()); const [amount, setAmount] = useState(""); const [categoryId, setCategoryId] = useState(""); const [note, setNote] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  const parties = useQuery({ queryKey: ["expense-payees"], queryFn: () => get<Party[]>("/parties?type=SUPPLIER") }); const expenses = useInfiniteQuery({ queryKey: ["expenses"], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => get<CursorPage<Expense>>(`/expenses?limit=50${pageParam ? `&cursor=${encodeURIComponent(pageParam)}` : ""}`), getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined }); const expenseRows = expenses.data?.pages.flatMap((page) => page.items) ?? []; const categories = useQuery({ queryKey: ["expense-categories"], queryFn: () => get<Array<{ id: string; name: string }>>("/expenses/categories") });
  const payeePickerOptions = partyPicker("SUPPLIER");
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { const draft = await post<{ id: string }>("/expenses", { amountRial: displayToRial(amount, currency), categoryId, txnDate: date, note: note || undefined, payeeId: payeeId || undefined }); setAdding(false); setAmount(""); setNote(""); await invalidate(); navigate("/app/expenses/" + draft.id); } catch (cause) { setError(messageOf(cause)); } finally { setBusy(false); } };
  return <PageHeader title="هزینه‌ها" subtitle="هزینه‌های جاری این شعبه را ثبت کنید" actions={<button className="button button-primary" onClick={() => setAdding(!adding)}><ReceiptText size={17} />ثبت هزینه</button>}>
    {adding && <Modal open={adding} onClose={() => setAdding(false)} title="هزینهٔ جدید" description="پیش‌نویس هزینه را ذخیره کنید؛ پیش از ثبت مالی می‌توانید آن را ویرایش یا حذف کنید."><form className="card inline-form" onSubmit={(event) => void submit(event)}><SectionTitle title="هزینهٔ جدید" /><div className="form-grid"><JalaliDatePicker value={date} onChange={setDate} label="تاریخ هزینه" /><Field label={`مبلغ (${currency === "IRT" ? "تومان" : "ریال"})`} value={amount} onChange={setAmount} inputMode={currency === "IRT" ? "decimal" : "numeric"} required /><SelectField label="دسته‌بندی" value={categoryId} onChange={setCategoryId} options={(categories.data ?? []).map((item) => ({ value: item.id, label: item.name }))} onAdd={() => setQuickCategoryOpen(true)} /><SelectField label="پرداخت‌کننده" value={payeeId} onChange={setPayeeId} options={(parties.data ?? []).map((item) => ({ value: item.id, label: item.name }))} optionsKey={payeePickerOptions.key} loadOptions={payeePickerOptions.load} placeholder="بدون پرداخت‌کننده" onAdd={() => setQuickPartyOpen(true)} /><Field label="توضیح" value={note} onChange={setNote} placeholder="اختیاری" /></div>{error && <p className="form-error">{error}</p>}<SubmitButton busy={busy}>ذخیرهٔ پیش‌نویس هزینه</SubmitButton></form></Modal>}
    <QuickPartyModal open={quickPartyOpen} type="SUPPLIER" onClose={() => setQuickPartyOpen(false)} onCreated={(party) => { setPayeeId(party.id); void invalidate(); }} /><QuickExpenseCategoryModal open={quickCategoryOpen} onClose={() => setQuickCategoryOpen(false)} onCreated={(category) => { setCategoryId(category.id); void invalidate(); }} />{expenses.isError && <InlineError error={expenses.error} retry={() => void expenses.refetch()} />}{expenses.isPending ? <LoadingBlock /> : <><DataRows icon={ReceiptText} onRowClick={(id) => navigate("/app/expenses/" + id)} rows={expenseRows.map((item) => ({ id: item.id, title: item.category, subtitle: `${item.expenseNo ?? "پیش‌نویس هزینه"} · ${jalaliDate(item.date)}${item.note ? ` · ${item.note}` : ""}`, amount: money(item.amountRial, currency), status: statusLabel(item.status) }))} emptyTitle="هزینه‌ای ثبت نشده" emptyText="هزینه‌های روزمره با تاریخ و دسته‌بندی ثبت می‌شوند." /><LoadMoreButton hasMore={Boolean(expenses.hasNextPage)} isLoading={expenses.isFetchingNextPage} onClick={() => void expenses.fetchNextPage()} /></>}
  </PageHeader>;
}

export function FinancePage({ currency }: { currency: MoneyCurrency }) {
  const invalidate = useInvalidate(); const navigate = useNavigate(); const [transactionOpen, setTransactionOpen] = useState(false); const [closeOpen, setCloseOpen] = useState(false); const [periodOpen, setPeriodOpen] = useState(false); const [quickPartyOpen, setQuickPartyOpen] = useState(false); const [quickAccountOpen, setQuickAccountOpen] = useState(false); const [quickAccountTarget, setQuickAccountTarget] = useState<"transaction" | "close">("transaction"); const [kind, setKind] = useState<"RECEIPT" | "PAYMENT" | "TRANSFER">("RECEIPT"); const [amount, setAmount] = useState(""); const [accountId, setAccountId] = useState(""); const [toAccountId, setToAccountId] = useState(""); const [partyId, setPartyId] = useState(""); const [txnDate, setTxnDate] = useState(() => todayISO()); const [method, setMethod] = useState("CASH"); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const [showAccountForm, setShowAccountForm] = useState(false); const [newAccountName, setNewAccountName] = useState(""); const [newAccountKind, setNewAccountKind] = useState("BANK"); const [closeDate, setCloseDate] = useState(() => todayISO()); const [closeAccountId, setCloseAccountId] = useState(""); const [countedBalance, setCountedBalance] = useState(""); const [closeNote, setCloseNote] = useState(""); const [closeError, setCloseError] = useState(""); const [closeBusy, setCloseBusy] = useState(false); const [periodStart, setPeriodStart] = useState(() => todayISO()); const [periodEnd, setPeriodEnd] = useState(() => todayISO()); const [periodReason, setPeriodReason] = useState(""); const [periodError, setPeriodError] = useState(""); const [periodBusy, setPeriodBusy] = useState(false); const [reopenId, setReopenId] = useState(""); const [reopenReason, setReopenReason] = useState("");
  const accounts = useQuery({ queryKey: ["accounts"], queryFn: () => get<CashAccount[]>("/finance/accounts") }); const parties = useQuery({ queryKey: ["finance-parties"], queryFn: () => get<Party[]>("/parties?type=BOTH") }); const transactions = useInfiniteQuery({ queryKey: ["transactions", sessionStorage.getItem("shopro_business_id"), sessionStorage.getItem("shopro_branch_id")], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => get<CursorPage<{ id: string; kind: string; date: string; amountRial: string; fromAccount: string | null; toAccount: string | null; method: string }>>(`/finance/transactions?limit=50${pageParam ? `&cursor=${encodeURIComponent(pageParam)}` : ""}`), getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined }); const transactionRows = transactions.data?.pages.flatMap((page) => page.items) ?? []; const closes = useInfiniteQuery({ queryKey: ["cash-closes", sessionStorage.getItem("shopro_business_id"), sessionStorage.getItem("shopro_branch_id")], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => get<CursorPage<{ id: string; date: string; account: string; systemBalanceRial: string; countedBalanceRial: string; differenceRial: string; note: string | null }>>(`/finance/cash-closes?limit=50${pageParam ? `&cursor=${encodeURIComponent(pageParam)}` : ""}`), getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined }); const closeRows = closes.data?.pages.flatMap((page) => page.items) ?? []; const periods = useQuery({ queryKey: ["closed-periods"], queryFn: () => get<Array<{ id: string; startDate: string; endDate: string; closeReason: string; reopenReason: string | null; reopenedAt: string | null; isClosed: boolean }>>("/finance/closed-periods") });
  const financePartyPickerOptions = partyPicker(kind === "RECEIPT" ? "CUSTOMER" : "SUPPLIER");
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { const amountRial = displayToRial(amount, currency); const key = newOperationId(); if (kind === "TRANSFER") await post("/cash-transactions/transfers", { amountRial, fromFinanceAccountId: accountId, toFinanceAccountId: toAccountId, txnDate }, { "Idempotency-Key": key }); else await post(`/cash-transactions/${kind === "RECEIPT" ? "receipts" : "payments"}`, { amountRial, financeAccountId: accountId, method, txnDate, ...(partyId ? { partyId } : {}) }, { "Idempotency-Key": key }); setAmount(""); setTransactionOpen(false); await invalidate(); } catch (cause) { setError(messageOf(cause)); } finally { setBusy(false); } };
  const addAccount = async (event: FormEvent) => { event.preventDefault(); setError(""); try { await post("/finance/accounts", { name: newAccountName, kind: newAccountKind }); setNewAccountName(""); setShowAccountForm(false); await invalidate(); } catch (cause) { setError(messageOf(cause)); } };
  const submitClose = async (event: FormEvent) => { event.preventDefault(); setCloseBusy(true); setCloseError(""); try { const amountRial = displayToRial(countedBalance, currency); if (!amountRial) throw new Error("موجودی شمارش‌شده را وارد کنید."); if (!closeAccountId) throw new Error("حساب صندوق یا بانک را انتخاب کنید."); await post("/finance/cash-closes", { financeAccountId: closeAccountId, closeDate, countedBalanceRial: amountRial, ...(closeNote.trim() ? { note: closeNote.trim() } : {}) }, { "Idempotency-Key": newOperationId() }); setCountedBalance(""); setCloseNote(""); await invalidate(); } catch (cause) { setCloseError(messageOf(cause)); } finally { setCloseBusy(false); } };
  const closePeriod = async (event: FormEvent) => { event.preventDefault(); setPeriodBusy(true); setPeriodError(""); try { await post("/finance/closed-periods", { startDate: periodStart, endDate: periodEnd, reason: periodReason }); setPeriodReason(""); await invalidate(); } catch (cause) { setPeriodError(messageOf(cause)); } finally { setPeriodBusy(false); } };
  const reopenPeriod = async () => { if (!reopenId) return; setPeriodBusy(true); setPeriodError(""); try { await post(`/finance/closed-periods/${reopenId}/reopen`, { reason: reopenReason }); setReopenId(""); setReopenReason(""); await invalidate(); } catch (cause) { setPeriodError(messageOf(cause)); } finally { setPeriodBusy(false); } };
  return <PageHeader title="صندوق و بانک" subtitle="ماندهٔ حساب‌ها و گردش دریافت و پرداخت" actions={<Link to="/app/reports" className="button button-secondary">گزارش مالی</Link>}><div className="finance-tabs">{([["RECEIPT", "دریافت"], ["PAYMENT", "پرداخت"], ["TRANSFER", "انتقال"]] as const).map(([value, label]) => <button key={value} className={kind === value ? "active" : ""} onClick={() => { setKind(value); setTransactionOpen(true); setError(""); }}>{label}</button>)}</div>
    <Modal open={transactionOpen} onClose={() => setTransactionOpen(false)} title={kind === "RECEIPT" ? "ثبت دریافت وجه" : kind === "PAYMENT" ? "ثبت پرداخت" : "انتقال بین حساب‌ها"} description="حساب‌ها و مبلغ را بررسی و ثبت تراکنش را تأیید کنید."><form className="modal-entry-form" onSubmit={(event) => void submit(event)}><SectionTitle title={kind === "RECEIPT" ? "ثبت دریافت وجه" : kind === "PAYMENT" ? "ثبت پرداخت" : "انتقال بین حساب‌ها"} /><div className="form-grid"><JalaliDatePicker value={txnDate} onChange={setTxnDate} label="تاریخ سند" /><Field label={`مبلغ (${currency === "IRT" ? "تومان" : "ریال"})`} value={amount} onChange={setAmount} inputMode={currency === "IRT" ? "decimal" : "numeric"} required /><SelectField label={kind === "RECEIPT" ? "واریز به حساب" : "حساب مبدأ"} value={accountId} onChange={setAccountId} options={(accounts.data ?? []).map((item) => ({ value: item.id, label: item.name }))} onAdd={() => { setQuickAccountTarget("transaction"); setQuickAccountOpen(true); }} />{kind === "TRANSFER" ? <SelectField label="حساب مقصد" value={toAccountId} onChange={setToAccountId} options={(accounts.data ?? []).filter((item) => item.id !== accountId).map((item) => ({ value: item.id, label: item.name }))} onAdd={() => { setQuickAccountTarget("transaction"); setQuickAccountOpen(true); }} /> : <><SelectField label="طرف‌حساب (اختیاری)" value={partyId} onChange={setPartyId} options={(parties.data ?? []).filter((party) => kind === "RECEIPT" ? ["CUSTOMER", "BOTH"].includes(party.type) : ["SUPPLIER", "BOTH"].includes(party.type)).map((party) => ({ value: party.id, label: party.name }))} optionsKey={financePartyPickerOptions.key} loadOptions={financePartyPickerOptions.load} placeholder="دریافت / پرداخت متفرقه" onAdd={() => setQuickPartyOpen(true)} /><SelectField label="روش" value={method} onChange={setMethod} options={[{ value: "CASH", label: "نقدی" }, { value: "POS", label: "کارت‌خوان" }, { value: "BANK", label: "بانکی" }, { value: "OTHER", label: "سایر" }]} /></>}</div>{error && <p className="form-error">{error}</p>}<SubmitButton busy={busy}>{kind === "TRANSFER" ? "ثبت انتقال" : kind === "RECEIPT" ? "ثبت دریافت" : "ثبت پرداخت"}</SubmitButton></form></Modal>
    {showAccountForm && <Modal open={showAccountForm} onClose={() => setShowAccountForm(false)} title="حساب مالی تازه" description="حساب صندوق یا بانک برای همین شعبه ساخته می‌شود."><form className="card inline-form" onSubmit={(event) => void addAccount(event)}><SectionTitle title="افزودن حساب مالی" /><div className="form-grid"><Field label="نام حساب" value={newAccountName} onChange={setNewAccountName} required /><SelectField label="نوع حساب" value={newAccountKind} onChange={setNewAccountKind} options={[{ value: "CASH", label: "صندوق" }, { value: "BANK", label: "بانک" }, { value: "POS", label: "کارت‌خوان" }, { value: "OTHER", label: "سایر" }]} /></div>{error && <p className="form-error">{error}</p>}<SubmitButton>ساخت حساب</SubmitButton></form></Modal>}
    <QuickPartyModal open={quickPartyOpen} type={kind === "RECEIPT" ? "CUSTOMER" : "SUPPLIER"} onClose={() => setQuickPartyOpen(false)} onCreated={(party) => { setPartyId(party.id); void invalidate(); }} /><QuickAccountModal open={quickAccountOpen} onClose={() => setQuickAccountOpen(false)} onCreated={(account) => { if (quickAccountTarget === "close") setCloseAccountId(account.id); else setAccountId(account.id); void invalidate(); }} /><section className="card account-grid"><SectionTitle title="حساب‌های فعال" action={<button type="button" className="button button-text" onClick={() => setShowAccountForm(true)}>افزودن حساب</button>} />{accounts.isPending ? <LoadingBlock /> : accounts.data?.length ? accounts.data.map((account) => <Link className="account-tile" key={account.id} to={"/app/finance/account/" + account.id}><span className="icon-tile emerald"><Wallet size={19} /></span><span className="row-grow"><strong>{account.name}</strong><small>{account.kind}</small></span><strong>{money(account.balanceRial, currency)}</strong></Link>) : <EmptyState icon={Wallet} title="حسابی ندارید" text="حساب صندوق اولیه در زمان ساخت کسب‌وکار ایجاد شده است." />}</section>
    <button type="button" className="button button-secondary" onClick={() => setCloseOpen(true)}>ثبت بستن صندوق</button><Modal open={closeOpen} onClose={() => setCloseOpen(false)} title="بستن صندوق" description="موجودی را با ماندهٔ دفتری مقایسه و ثبت کنید."><form className="modal-entry-form cash-close-form" onSubmit={(event) => void submitClose(event)}><SectionTitle title="بستن صندوق" /><p className="muted">موجودی دفتری تا تاریخ انتخابی را سرور محاسبه می‌کند و اختلاف شمارش را با سند مالی ثبت خواهد کرد.</p><div className="form-grid"><JalaliDatePicker value={closeDate} onChange={setCloseDate} label="تاریخ بستن" /><SelectField label="حساب صندوق یا بانک" value={closeAccountId} onChange={setCloseAccountId} options={(accounts.data ?? []).map((item) => ({ value: item.id, label: item.name }))} onAdd={() => { setQuickAccountTarget("close"); setQuickAccountOpen(true); }} /><Field label={`موجودی شمارش‌شده (${currency === "IRT" ? "تومان" : "ریال"})`} value={countedBalance} onChange={setCountedBalance} inputMode={currency === "IRT" ? "decimal" : "numeric"} required /><Field label="توضیح اختلاف" value={closeNote} onChange={setCloseNote} placeholder="اختیاری" /></div>{closeError && <InlineError error={closeError} />}{accounts.isError && <InlineError error={accounts.error} retry={() => void accounts.refetch()} />}<SubmitButton busy={closeBusy}>محاسبه و ثبت بستن صندوق</SubmitButton></form></Modal>
    <button type="button" className="button button-secondary" onClick={() => setPeriodOpen(true)}>بستن دورهٔ مالی</button><Modal open={periodOpen} onClose={() => setPeriodOpen(false)} title="بستن دورهٔ مالی" description="بازه و دلیل بستن را بررسی کنید."><form className="modal-entry-form period-close-form" onSubmit={(event) => void closePeriod(event)}><SectionTitle title="بستن دورهٔ مالی" /><p className="muted">ثبت سند در بازهٔ بسته متوقف می‌شود. پیش‌نویس‌های باز باید پیش از بستن تعیین تکلیف شوند.</p><div className="form-grid"><JalaliDatePicker value={periodStart} onChange={setPeriodStart} label="شروع دوره" /><JalaliDatePicker value={periodEnd} onChange={setPeriodEnd} label="پایان دوره" /><Field label="دلیل بستن" value={periodReason} onChange={setPeriodReason} required placeholder="مثلاً پایان ماه" /></div>{periodError && <InlineError error={periodError} />}{periods.isError && <InlineError error={periods.error} retry={() => void periods.refetch()} />}<SubmitButton busy={periodBusy}>بستن بازهٔ انتخاب‌شده</SubmitButton><div className="period-list">{periods.data?.map((period) => <article className="period-row" key={period.id}><div><strong>{jalaliDate(period.startDate)} تا {jalaliDate(period.endDate)}</strong><small>{period.isClosed ? `بسته: ${period.closeReason}` : `بازشده: ${period.reopenReason ?? "بدون توضیح"}`}</small></div>{period.isClosed && <button className="button button-secondary" type="button" onClick={() => { setReopenId(period.id); setPeriodError(""); }}>بازگشایی</button>}</article>)}</div><Modal open={!!reopenId} onClose={() => setReopenId("")} title="بازگشایی دورهٔ مالی" description="دلیل بازگشایی در سابقهٔ مالی ثبت می‌شود.">{reopenId && <div className="reopen-period-form"><Field label="دلیل بازگشایی" value={reopenReason} onChange={setReopenReason} required /><button className="button button-danger" type="button" disabled={periodBusy || reopenReason.trim().length < 3} onClick={() => void reopenPeriod()}>ثبت بازگشایی</button></div>}</Modal></form></Modal>
    <section className="card"><SectionTitle title="تراکنش‌های اخیر" />{transactions.isError && <InlineError error={transactions.error} retry={() => void transactions.refetch()} />}{transactions.isPending ? <LoadingBlock /> : <><DataRows icon={Wallet} onRowClick={(id) => navigate("/app/finance/transaction/" + id)} rows={transactionRows.map((item) => ({ id: item.id, title: cashKindLabel(item.kind), subtitle: `${item.fromAccount ?? item.toAccount ?? "حساب مالی"} · ${jalaliDate(item.date)}`, amount: money(item.amountRial, currency), tone: item.kind === "RECEIPT" ? "posted" : "draft" }))} emptyTitle="تراکنشی ثبت نشده" emptyText="دریافت‌ها و پرداخت‌های ثبت‌شده در این بخش دیده می‌شوند." /><LoadMoreButton hasMore={Boolean(transactions.hasNextPage)} isLoading={transactions.isFetchingNextPage} onClick={() => void transactions.fetchNextPage()} /></>}</section>
    <section className="card"><SectionTitle title="بستن‌های اخیر صندوق" />{closes.isError && <InlineError error={closes.error} retry={() => void closes.refetch()} />}{closes.isPending ? <LoadingBlock /> : <><DataRows icon={Wallet} onRowClick={(id) => navigate("/app/finance/close/" + id)} rows={closeRows.map((item) => ({ id: item.id, title: `${item.account} · ${jalaliDate(item.date)}`, subtitle: `دفتری ${money(item.systemBalanceRial, currency)} · شمارش ${money(item.countedBalanceRial, currency)}${item.note ? ` · ${item.note}` : ""}`, amount: money(item.differenceRial, currency), tone: BigInt(item.differenceRial) === 0n ? "posted" : "draft" }))} emptyTitle="بستن صندوقی ثبت نشده" emptyText="پس از شمارش صندوق، ماندهٔ دفتری و اختلاف اینجا ثبت می‌شود." /><LoadMoreButton hasMore={Boolean(closes.hasNextPage)} isLoading={closes.isFetchingNextPage} onClick={() => void closes.fetchNextPage()} /></>}</section>
  </PageHeader>;
}

export function ReportsPage({ currency, role }: { currency: MoneyCurrency; role: string }) {
  const today = todayISO(); const [from, setFrom] = useState(today); const [to, setTo] = useState(today); const [range, setRange] = useState({ from: today, to: today });
  const dashboard = useQuery({ queryKey: ["report-dashboard", range], queryFn: () => get<Dashboard>(`/reports/dashboard?from=${range.from}&to=${range.to}`) }); const profitLoss = useQuery({ queryKey: ["profit-loss", range], queryFn: () => get<{ revenueRial: string; expenseRial: string; netProfitRial: string; accounts: Array<{ id: string; name: string; type: string; amountRial: string }> }>(`/reports/profit-loss?from=${range.from}&to=${range.to}`) }); const cashFlow = useQuery({ queryKey: ["cash-flow", range], queryFn: () => get<{ grossReceiptsRial: string; grossPaymentsRial: string; receiptsRial: string; paymentsRial: string; netCashFlowRial: string }>(`/reports/cash-flow?from=${range.from}&to=${range.to}`) });
  const receivables = useInfiniteQuery({ queryKey: ["report-receivables"], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => get<CursorPage<PartyBalance>>(`/reports/receivables?limit=50${pageParam ? `&cursor=${encodeURIComponent(pageParam)}` : ""}`), getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined }); const payables = useInfiniteQuery({ queryKey: ["report-payables"], initialPageParam: undefined as string | undefined, queryFn: ({ pageParam }) => get<CursorPage<PartyBalance>>(`/reports/payables?limit=50${pageParam ? `&cursor=${encodeURIComponent(pageParam)}` : ""}`), getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined });
  const receivableRows = receivables.data?.pages.flatMap((page) => page.items) ?? []; const payableRows = payables.data?.pages.flatMap((page) => page.items) ?? [];
  const [balanceExporting, setBalanceExporting] = useState<"receivables" | "payables" | null>(null); const [balanceExportError, setBalanceExportError] = useState("");
  const canSeeTrialBalance = role === "OWNER" || role === "ACCOUNTANT";
  const trialBalance = useQuery({ queryKey: ["trial-balance", range], queryFn: () => get<{ accounts: Array<{ code: string; name: string; debitRial: string; creditRial: string }>; totalDebitRial: string; totalCreditRial: string }>(`/reports/trial-balance?from=${range.from}&to=${range.to}`), enabled: canSeeTrialBalance });
  const exportProfitLoss = () => { if (!profitLoss.data) return; downloadCsv("shopro-profit-loss.csv", [["گزارش", "سود و زیان"], ["از تاریخ", range.from], ["تا تاریخ", range.to], ["درآمد کل (ریال)", profitLoss.data.revenueRial], ["هزینه کل (ریال)", profitLoss.data.expenseRial], ["سود خالص (ریال)", profitLoss.data.netProfitRial], [], ["حساب", "گروه", "مبلغ (ریال)"], ...profitLoss.data.accounts.map((item) => [item.name, item.type === "REVENUE" ? "درآمد" : "هزینه", item.amountRial])]); };
  const exportCashFlow = () => { if (!cashFlow.data) return; downloadCsv("shopro-cash-flow.csv", [["گزارش", "جریان نقد"], ["از تاریخ", range.from], ["تا تاریخ", range.to], ["دریافت ناخالص (ریال)", cashFlow.data.grossReceiptsRial], ["پرداخت ناخالص (ریال)", cashFlow.data.grossPaymentsRial], ["خالص جریان نقد (ریال)", cashFlow.data.netCashFlowRial]]); };
  const exportDashboard = () => { if (!dashboard.data) return; downloadCsv("shopro-sales-summary.csv", [["گزارش", "خلاصهٔ فروش و عملیات"], ["از تاریخ", range.from], ["تا تاریخ", range.to], ["واحد مبالغ", "ریال"], [], ["شاخص", "مقدار"], ["فروش ناخالص ثبت‌شده", dashboard.data.salesRial], ["فروش خالص پیش از مالیات", dashboard.data.netSalesRial], ["دریافت ثبت‌شده", dashboard.data.receiptsRial], ["هزینه ثبت‌شده", dashboard.data.expensesRial], ["سود ناخالص", dashboard.data.grossProfitRial ?? "در دسترس نیست"], ["ماندهٔ صندوق و بانک", dashboard.data.cashPositionRial], ["تعداد فاکتور فروش", String(dashboard.data.salesCount)], ["تعداد هزینه", String(dashboard.data.expenseCount)]]); };
  const exportPartyBalances = async (kind: "receivables" | "payables", title: string) => {
    if (balanceExporting) return;
    setBalanceExportError(""); setBalanceExporting(kind);
    try {
      const rows: PartyBalance[] = []; let cursor: string | undefined;
      do {
        const page = await get<CursorPage<PartyBalance>>(`/reports/${kind}?limit=100${cursor ? `&cursor=${encodeURIComponent(cursor)}` : ""}`);
        rows.push(...page.items); cursor = page.nextCursor ?? undefined;
        if (rows.length >= 10_000 && cursor) throw new Error("بیش از ۱۰٬۰۰۰ طرف‌حساب وجود دارد؛ خروجی برای جلوگیری از فایل ناقص ساخته نشد.");
      } while (cursor);
      const total = rows.reduce((sum, row) => sum + BigInt(row.balanceRial), 0n).toString();
      downloadCsv(`shopro-${kind}.csv`, [["گزارش", title], ["مبنا", "ماندهٔ فعلی دفتر مالی؛ بدون فیلتر بازهٔ تاریخ"], ["تعداد طرف‌حساب", String(rows.length)], ["جمع مانده (ریال)", total], [], ["طرف‌حساب", "مانده (ریال)"], ...rows.map((row) => [row.name, row.balanceRial])]);
    } catch (cause) { setBalanceExportError(messageOf(cause)); }
    finally { setBalanceExporting(null); }
  };
  const exportTrialBalance = () => { if (!trialBalance.data) return; downloadCsv("shopro-trial-balance.csv", [["گزارش", "تراز آزمایشی"], ["از تاریخ", range.from], ["تا تاریخ", range.to], ["جمع بدهکار (ریال)", trialBalance.data.totalDebitRial], ["جمع بستانکار (ریال)", trialBalance.data.totalCreditRial], [], ["کد حساب", "حساب", "بدهکار (ریال)", "بستانکار (ریال)"], ...trialBalance.data.accounts.map((row) => [row.code, row.name, row.debitRial, row.creditRial])]); };
  const reportQueries = [dashboard, profitLoss, cashFlow, receivables, payables, ...(canSeeTrialBalance ? [trialBalance] : [])];
  return <PageHeader title="گزارش‌ها" subtitle="گزارش‌های مالی مبتنی بر اسناد ثبت‌شده" actions={<button type="button" className="button button-secondary" disabled={!dashboard.data} onClick={exportDashboard}><Download size={15} />خلاصهٔ فروش CSV</button>}><section className="card report-range"><JalaliDatePicker value={from} onChange={setFrom} label="از تاریخ" /><JalaliDatePicker value={to} onChange={setTo} label="تا تاریخ" /><button className="button button-primary" onClick={() => setRange({ from, to })}>اعمال بازه</button></section>{reportQueries.some((query) => query.isError) && <InlineError error={reportQueries.find((query) => query.isError)?.error} retry={() => { for (const query of reportQueries) void query.refetch(); }} />}
    <div className="metric-grid report-metrics"><MetricCard label="فروش خالص" value={dashboard.data ? money(dashboard.data.netSalesRial, currency) : "—"} detail="بدون احتساب مالیات فروش" icon={ShoppingCart} tone="emerald" /><MetricCard label="سود خالص" value={profitLoss.data ? money(profitLoss.data.netProfitRial, currency) : "—"} detail="درآمد منهای هزینه" icon={ReceiptText} tone="violet" /><MetricCard label="خالص جریان نقد" value={cashFlow.data ? money(cashFlow.data.netCashFlowRial, currency) : "—"} detail="دریافت و پرداخت ناخالص، با احتساب بازپرداخت‌ها" icon={Wallet} tone="blue" /><MetricCard label="هزینه‌ها" value={profitLoss.data ? money(profitLoss.data.expenseRial, currency) : "—"} detail="ثبت‌شده در بازه" icon={ReceiptText} tone="amber" /></div>
    <section className="card"><SectionTitle title="درآمد و هزینه بر اساس حساب" action={<button type="button" className="button button-secondary" disabled={!profitLoss.data} onClick={exportProfitLoss}><Download size={15} />دریافت CSV</button>} />{profitLoss.isPending ? <LoadingBlock /> : <DataRows rows={(profitLoss.data?.accounts ?? []).map((item) => ({ id: item.id, title: item.name, subtitle: item.type === "REVENUE" ? "درآمد" : "هزینه", amount: money(item.amountRial, currency) }))} emptyTitle="گردشی در این بازه نیست" emptyText="با ثبت سندهای فروش و هزینه، این گزارش تکمیل می‌شود." />}</section>
    <section className="card"><SectionTitle title="جریان نقد" action={<button type="button" className="button button-secondary" disabled={!cashFlow.data} onClick={exportCashFlow}><Download size={15} />دریافت CSV</button>} />{cashFlow.isPending ? <LoadingBlock /> : <DataRows rows={cashFlow.data ? [{ id: "gross-receipts", title: "دریافت ناخالص", subtitle: "با احتساب بازپرداخت‌ها", amount: money(cashFlow.data.grossReceiptsRial, currency) }, { id: "gross-payments", title: "پرداخت ناخالص", subtitle: "جمع پرداخت‌ها", amount: money(cashFlow.data.grossPaymentsRial, currency) }, { id: "net-flow", title: "خالص جریان نقد", subtitle: `${range.from} تا ${range.to}`, amount: money(cashFlow.data.netCashFlowRial, currency) }] : []} emptyTitle="گردشی در این بازه نیست" emptyText="پس از ثبت دریافت یا پرداخت، خلاصهٔ جریان نقد اینجا نمایش داده می‌شود." />}</section>
    <section className="card"><SectionTitle title="مطالبات از مشتریان" action={<button type="button" className="button button-secondary" disabled={balanceExporting !== null || receivables.isPending} onClick={() => void exportPartyBalances("receivables", "مطالبات فعلی")}><Download size={15} />{balanceExporting === "receivables" ? "در حال آماده‌سازی…" : "دریافت CSV"}</button>} />{receivables.isPending ? <LoadingBlock /> : <><DataRows rows={receivableRows.map((row) => ({ id: row.id, title: row.name, subtitle: "ماندهٔ بدهکار فعلی", amount: money(row.balanceRial, currency) }))} emptyTitle="مطالبه‌ای ثبت نشده" emptyText="مانده‌ها از دفتر مالی محاسبه می‌شوند." /><LoadMoreButton hasMore={Boolean(receivables.hasNextPage)} isLoading={receivables.isFetchingNextPage} onClick={() => void receivables.fetchNextPage()} /></>}</section>
    <section className="card"><SectionTitle title="بدهی به تأمین‌کنندگان" action={<button type="button" className="button button-secondary" disabled={balanceExporting !== null || payables.isPending} onClick={() => void exportPartyBalances("payables", "بدهی‌های فعلی")}><Download size={15} />{balanceExporting === "payables" ? "در حال آماده‌سازی…" : "دریافت CSV"}</button>} />{payables.isPending ? <LoadingBlock /> : <><DataRows rows={payableRows.map((row) => ({ id: row.id, title: row.name, subtitle: "ماندهٔ بستانکار فعلی", amount: money(row.balanceRial, currency) }))} emptyTitle="بدهی‌ای ثبت نشده" emptyText="مانده‌ها از دفتر مالی محاسبه می‌شوند." /><LoadMoreButton hasMore={Boolean(payables.hasNextPage)} isLoading={payables.isFetchingNextPage} onClick={() => void payables.fetchNextPage()} /></>}</section>
    {balanceExportError && <InlineError error={balanceExportError} />}
    {canSeeTrialBalance && <section className="card"><SectionTitle title="تراز آزمایشی" action={<button type="button" className="button button-secondary" disabled={!trialBalance.data} onClick={exportTrialBalance}><Download size={15} />دریافت CSV</button>} />{trialBalance.isPending ? <LoadingBlock /> : <><p className="muted">از {jalaliDate(range.from)} تا {jalaliDate(range.to)} · بدهکار {money(trialBalance.data?.totalDebitRial ?? "0", currency)} · بستانکار {money(trialBalance.data?.totalCreditRial ?? "0", currency)}</p><DataRows rows={(trialBalance.data?.accounts ?? []).map((row) => ({ id: row.code, title: `${row.code} · ${row.name}`, subtitle: `بستانکار ${money(row.creditRial, currency)}`, amount: money(row.debitRial, currency) }))} emptyTitle="گردشی در این بازه نیست" emptyText="دفتر کل در بازهٔ انتخابی گردش ثبت‌شده ندارد." /></>}</section>}
    <section className="card report-disclaimer"><FileText size={18} /><p>گزارش‌ها از اسناد ثبت‌شده و دفتر مالی ساخته می‌شوند. پیش‌نویس‌ها در جمع‌ها وارد نمی‌شوند.</p></section>
  </PageHeader>;
}

export function SettingsPage({ business, theme, setTheme }: { business: BusinessSummary; theme: string; setTheme: (value: string) => void }) {
  const invalidate = useInvalidate(); const [displayName, setDisplayName] = useState(business.displayName); const [currency, setCurrency] = useState(business.displayCurrency); const [branchName, setBranchName] = useState(""); const [branchCode, setBranchCode] = useState(""); const [phone, setPhone] = useState(""); const [role, setRole] = useState("CASHIER"); const [error, setError] = useState(""); const [success, setSuccess] = useState(""); const [showNewBusiness, setShowNewBusiness] = useState(false); const [newBusinessName, setNewBusinessName] = useState(""); const [newBusinessType, setNewBusinessType] = useState("فروشگاه"); const [newBranchName, setNewBranchName] = useState("شعبهٔ اصلی");
  const branches = useQuery({ queryKey: ["business-current"], queryFn: () => get<{ branches: Array<{ id: string; name: string; code: string }> }>("/businesses/current") }); const members = useQuery({ queryKey: ["business-members"], queryFn: () => get<Array<{ id: string; role: string; status: string; user: { phone: string; displayName: string | null }; branchIds: string[] }>>("/businesses/current/members") });
  const save = async (event: FormEvent) => { event.preventDefault(); setError(""); setSuccess(""); try { await patch("/businesses/current", { displayName, displayCurrency: currency }); await invalidate(); setSuccess("تنظیمات ذخیره شد."); } catch (cause) { setError(messageOf(cause)); } };
  const addBranch = async (event: FormEvent) => { event.preventDefault(); setError(""); try { await post("/businesses/current/branches", { name: branchName, code: branchCode }); setBranchName(""); setBranchCode(""); await invalidate(); setSuccess("شعبه اضافه شد."); } catch (cause) { setError(messageOf(cause)); } };
  const addMember = async (event: FormEvent) => { event.preventDefault(); setError(""); try { await post("/businesses/current/members", { phone, role, branchIds: (branches.data?.branches ?? []).map((item) => item.id) }); setPhone(""); await invalidate(); setSuccess("عضویت کاربر ثبت شد."); } catch (cause) { setError(messageOf(cause)); } };
  const createBusiness = async (event: FormEvent) => { event.preventDefault(); setError(""); try { const result = await post<{ id: string; branch: { id: string } }>("/businesses", { displayName: newBusinessName, businessType: newBusinessType, initialBranchName: newBranchName, displayCurrency: currency }); sessionStorage.setItem("shopro_business_id", result.id); sessionStorage.setItem("shopro_branch_id", result.branch.id); await invalidate(); window.location.assign("/app"); } catch (cause) { setError(messageOf(cause)); } };
  return <PageHeader title="تنظیمات کسب‌وکار" subtitle="مشخصات، شعبه‌ها و اعضای کسب‌وکار" actions={<button className="button button-secondary" type="button" onClick={() => setShowNewBusiness(!showNewBusiness)}><CirclePlus size={17} />افزودن کسب‌وکار</button>}>
    {showNewBusiness && <form className="card inline-form" onSubmit={(event) => void createBusiness(event)}><SectionTitle title="کسب‌وکار تازه" /><div className="form-grid"><Field label="نام کسب‌وکار" value={newBusinessName} onChange={setNewBusinessName} required /><Field label="نوع کسب‌وکار" value={newBusinessType} onChange={setNewBusinessType} required /><Field label="نام شعبهٔ اول" value={newBranchName} onChange={setNewBranchName} required /></div><SubmitButton>ساخت کسب‌وکار و جابه‌جایی</SubmitButton></form>}
    <form className="card inline-form" onSubmit={(event) => void save(event)}><SectionTitle title="مشخصات عمومی" /><div className="form-grid"><Field label="نام کسب‌وکار" value={displayName} onChange={setDisplayName} required /><SelectField label="واحد نمایش پول" value={currency} onChange={(value) => setCurrency(value as typeof currency)} options={[{ value: "IRT", label: "تومان" }, { value: "IRR", label: "ریال" }]} /><SelectField label="پوستهٔ نمایش" value={theme} onChange={setTheme} options={[{ value: "auto", label: "همگام با دستگاه" }, { value: "light", label: "روشن" }, { value: "dark", label: "تیره" }]} /></div><SubmitButton>ذخیرهٔ تنظیمات</SubmitButton></form>
    <form className="card inline-form" onSubmit={(event) => void addBranch(event)}><SectionTitle title="شعبه‌ها" /><div className="branch-list">{(branches.data?.branches ?? []).map((branch) => <div key={branch.id} className="branch-row"><strong>{branch.name}</strong><span>{branch.code}</span>{branch.id === sessionStorage.getItem("shopro_branch_id") && <small>شعبهٔ جاری</small>}</div>)}</div><div className="form-grid"><Field label="نام شعبهٔ تازه" value={branchName} onChange={setBranchName} required /><Field label="کد شعبه" value={branchCode} onChange={setBranchCode} required placeholder="مثلاً NORTH" /></div><button className="button button-secondary" type="submit">افزودن شعبه</button></form>
    <form className="card inline-form" onSubmit={(event) => void addMember(event)}><SectionTitle title="افزودن عضو" /><p className="muted">کاربر باید یک‌بار با شمارهٔ خودش وارد شده باشد؛ دسترسی به شعبه‌های موجود داده می‌شود.</p><div className="form-grid"><Field label="شمارهٔ موبایل" value={phone} onChange={setPhone} required inputMode="tel" dir="ltr" /><SelectField label="نقش" value={role} onChange={setRole} options={[{ value: "MANAGER", label: "مدیر شعبه" }, { value: "ACCOUNTANT", label: "حسابدار" }, { value: "CASHIER", label: "صندوقدار" }, { value: "VIEWER", label: "مشاهده‌گر" }]} /></div><SubmitButton>ثبت دسترسی عضو</SubmitButton></form>
    <section className="card"><SectionTitle title="اعضای کسب‌وکار" />{members.isPending ? <LoadingBlock /> : <DataRows icon={UsersRound} rows={(members.data ?? []).map((member) => ({ id: member.id, title: member.user.displayName ?? member.user.phone, subtitle: `${roleLabel(member.role)} · ${faNumber(member.branchIds.length)} شعبه`, status: member.status === "ACTIVE" ? "فعال" : "غیرفعال" }))} emptyTitle="عضوی اضافه نشده" emptyText="فهرست دسترسی اعضا اینجا نمایش داده می‌شود." />}</section>
    {error && <InlineError error={error} />}{success && <div className="notice notice-success">{success}</div>}
  </PageHeader>;
}

function displayToRial(value: string, currency: MoneyCurrency) { const normalized = toAsciiDigits(value).replace(/[٬,\s]/g, "").trim(); if (!normalized) return ""; if (currency === "IRT") { const match = /^(\d+)(?:[.٫](\d))?$/.exec(normalized); if (!match) throw new Error("مبلغ تومان حداکثر یک رقم اعشار می‌پذیرد."); return (BigInt(match[1]) * 10n + BigInt(match[2] ?? "0")).toString(); } if (!/^\d+$/.test(normalized)) throw new Error("مبلغ ریالی باید عدد صحیح باشد."); return BigInt(normalized).toString(); }
function statusLabel(status: string) { return ({ POSTED: "ثبت‌شده", DRAFT: "پیش‌نویس", VOIDED: "باطل‌شده" } as Record<string, string>)[status] ?? status; }
function typeLabel(type: string) { return ({ CUSTOMER: "مشتری", SUPPLIER: "تأمین‌کننده", BOTH: "مشتری و تأمین‌کننده" } as Record<string, string>)[type] ?? type; }
function roleLabel(role: string) { return ({ OWNER: "مالک", MANAGER: "مدیر", ACCOUNTANT: "حسابدار", CASHIER: "صندوقدار", VIEWER: "مشاهده‌گر" } as Record<string, string>)[role] ?? role; }
function cashKindLabel(kind: string) { return ({ RECEIPT: "دریافت وجه", PAYMENT: "پرداخت", TRANSFER: "انتقال", OPENING: "موجودی آغاز دوره" } as Record<string, string>)[kind] ?? kind; }
function XIcon() { return <span aria-hidden="true">×</span>; }
